  subroutine bin_struct_reallocate_count(struct_obj_ptr, lbound_, n) &
        bind(c, name='bin_struct_reallocate_count')
    type(c_ptr), intent(in), value :: struct_obj_ptr
    integer(c_int), value :: lbound_
    integer(c_size_t), value :: n
    type(bin_struct), pointer :: struct_obj

    call c_f_pointer(struct_obj_ptr, struct_obj)
    
    if (n == 0) then
      if (allocated(struct_obj%count)) deallocate(struct_obj%count)
    else
      if (allocated(struct_obj%count)) deallocate(struct_obj%count)
      allocate(struct_obj%count(lbound_:lbound_ + n - 1))
    endif
  end subroutine


  subroutine bin_struct_set_count(struct_obj_ptr, val_ptr, shape) &
      bind(c, name='bin_struct_set_count')
    type(c_ptr), intent(in), value :: struct_obj_ptr
    type(c_ptr), intent(in), value :: val_ptr
    integer(c_int), dimension(1), intent(in) :: shape
    type(bin_struct), pointer :: struct_obj
    real(c_double), pointer :: val(:)

    call c_f_pointer(struct_obj_ptr, struct_obj)
    if (c_associated(val_ptr)) then
      call c_f_pointer(val_ptr, val, shape)
      if (allocated(struct_obj%count)) then
         if ((size(struct_obj%count, 1) /= shape(1))) deallocate(struct_obj%count)
      endif
      if (.not. allocated(struct_obj%count)) allocate(struct_obj%count(shape(1)))
      struct_obj%count = val
    endif
  end subroutine

