  ! dispatch: bunch_struct%integer (6 fields)

  subroutine bunch_struct_get_integer(struct_obj_ptr, field_id, value_out) &
      bind(c, name='bunch_struct_get_integer')
    type(c_ptr), intent(in), value :: struct_obj_ptr
    integer(c_int), intent(in), value :: field_id
    integer(c_int), intent(out) :: value_out
    type(bunch_struct), pointer :: struct_obj
    call c_f_pointer(struct_obj_ptr, struct_obj)
    select case(field_id)
    case(0); value_out = struct_obj%ix_ele
    case(1); value_out = struct_obj%ix_bunch
    case(2); value_out = struct_obj%ix_turn
