    function allocate_fortran_extra_parsing_info_struct(n, element_size) result(ptr) bind(c)
      implicit none
      integer(c_int), value :: n
      integer(c_size_t), intent(out) :: element_size
      type(c_ptr) :: ptr
      type(extra_parsing_info_struct), pointer :: fptr
      type(extra_parsing_info_struct), pointer :: fptr_array(:)

      if (n <= 0) then
        allocate(fptr)
        ptr = c_loc(fptr)
        element_size = int(storage_size(fptr) / 8, c_size_t)
      else
        allocate(fptr_array(n))
        ptr = c_loc(fptr_array)
        element_size = int(storage_size(fptr_array(1)) / 8, c_size_t)
      end if
    end function

    subroutine deallocate_fortran_extra_parsing_info_struct(ptr, n) bind(c)
      implicit none
      type(c_ptr), value :: ptr
      integer(c_int), value :: n
      type(extra_parsing_info_struct), pointer :: fptr
      type(extra_parsing_info_struct), pointer :: fptr_array(:)

      if (c_associated(ptr)) then
        if (n <= 0) then
          call c_f_pointer(ptr, fptr)
          deallocate(fptr)
        else
          call c_f_pointer(ptr, fptr_array, [n])
          deallocate(fptr_array)
        end if
      end if
    end subroutine

  subroutine copy_fortran_extra_parsing_info_struct(src_ptr, dst_ptr) bind(c)
    implicit none
    type(c_ptr), value :: src_ptr, dst_ptr
    type(extra_parsing_info_struct), pointer :: src, dst

    if (c_associated(src_ptr) .and. c_associated(dst_ptr)) then
      call c_f_pointer(src_ptr, src)
      call c_f_pointer(dst_ptr, dst)
      dst = src  ! Fortran derived type assignment
    end if
  end subroutine

