    logical(c_bool), intent(out) :: is_allocated
    integer(c_size_t), intent(out) :: elem_size

    type(foil_struct_container_alloc), pointer :: ctr

    if (.not. c_associated(container_ptr)) then
       is_allocated = .false.
       return
