      integer(c_int), value :: n
      type(gg_taylor_struct), pointer :: fptr
      type(gg_taylor_struct), pointer :: fptr_array(:)

      if (c_associated(ptr)) then
        if (n <= 0) then
          call c_f_pointer(ptr, fptr)
          deallocate(fptr)
        else
          call c_f_pointer(ptr, fptr_array, [n])
          deallocate(fptr_array)
        end if
      end if
    end subroutine

