    end if
  end subroutine

  subroutine reallocate_lat_struct_container_data(container_ptr, lbound_, n) bind(c)
    implicit none
    type(c_ptr), value :: container_ptr
    integer(c_int), value :: lbound_
    integer(c_size_t), value :: n
    type(lat_struct_container_alloc), pointer :: ctr

    if (.not. c_associated(container_ptr)) return
    call c_f_pointer(container_ptr, ctr)

    if (n == 0) then
      if (allocated(ctr%data)) deallocate(ctr%data)
    else
      if (allocated(ctr%data)) deallocate(ctr%data)
      allocate(ctr%data(lbound_:lbound_ + n - 1))
    end if
  end subroutine

  subroutine access_lat_struct_container(container_ptr, d_ptr, bounds, is_allocated, elem_size) bind(c)
    use iso_c_binding
    implicit none
    type(c_ptr), value :: container_ptr
    type(c_ptr), intent(out) :: d_ptr
    integer(c_int), dimension(2), intent(out) :: bounds
    logical(c_bool), intent(out) :: is_allocated
    integer(c_size_t), intent(out) :: elem_size

    type(lat_struct_container_alloc), pointer :: ctr

    if (.not. c_associated(container_ptr)) then
       is_allocated = .false.
       return
    endif

    call c_f_pointer(container_ptr, ctr)

    if (allocated(ctr%data)) then
      is_allocated = .true.
      bounds(1) = int(lbound(ctr%data, 1), c_int)
      bounds(2) = int(ubound(ctr%data, 1), c_int)
      ! Use intrinsic storage_size (returns bits) divided by 8 for bytes
      elem_size = storage_size(ctr%data(bounds(1))) / 8
      d_ptr = c_loc(ctr%data(bounds(1)))
    else
      is_allocated = .false.
      d_ptr = c_null_ptr
      bounds = 0
      elem_size = 0
    endif
  end subroutine
    
  ! dispatch: lat_struct%integer (7 fields)

  subroutine lat_struct_get_integer(struct_obj_ptr, field_id, value_out) &
      bind(c, name='lat_struct_get_integer')
    type(c_ptr), intent(in), value :: struct_obj_ptr
    integer(c_int), intent(in), value :: field_id
    integer(c_int), intent(out) :: value_out
    type(lat_struct), pointer :: struct_obj
    call c_f_pointer(struct_obj_ptr, struct_obj)
    select case(field_id)
    case(0); value_out = struct_obj%version
    case(1); value_out = struct_obj%n_control_max
    case(2); value_out = struct_obj%n_ic_max
    case(3); value_out = struct_obj%input_taylor_order
    case(4); value_out = struct_obj%photon_type
    case(5); value_out = struct_obj%creation_hash
    case(6); value_out = struct_obj%ramper_slave_bookkeeping
    end select
