    call c_f_pointer(struct_obj_ptr, struct_obj)
    select case(field_id)
    case(0); struct_obj%version = value_in
    case(1); struct_obj%n_control_max = value_in
    case(2); struct_obj%n_ic_max = value_in
    case(3); struct_obj%input_taylor_order = value_in
    case(4); struct_obj%photon_type = value_in
