  !! named_number_struct

    function allocate_fortran_named_number_struct(n, element_size) result(ptr) bind(c)
      implicit none
      integer(c_int), value :: n
      integer(c_size_t), intent(out) :: element_size
      type(c_ptr) :: ptr
      type(named_number_struct), pointer :: fptr
      type(named_number_struct), pointer :: fptr_array(:)

      if (n <= 0) then
        allocate(fptr)
        ptr = c_loc(fptr)
        element_size = int(storage_size(fptr) / 8, c_size_t)
      else
        allocate(fptr_array(n))
        ptr = c_loc(fptr_array)
        element_size = int(storage_size(fptr_array(1)) / 8, c_size_t)
      end if
    end function

    subroutine deallocate_fortran_named_number_struct(ptr, n) bind(c)
      implicit none
      type(c_ptr), value :: ptr
      integer(c_int), value :: n
      type(named_number_struct), pointer :: fptr
      type(named_number_struct), pointer :: fptr_array(:)

      if (c_associated(ptr)) then
        if (n <= 0) then
          call c_f_pointer(ptr, fptr)
          deallocate(fptr)
        else
          call c_f_pointer(ptr, fptr_array, [n])
          deallocate(fptr_array)
        end if
      end if
    end subroutine

  subroutine copy_fortran_named_number_struct(src_ptr, dst_ptr) bind(c)
    implicit none
    type(c_ptr), value :: src_ptr, dst_ptr
    type(named_number_struct), pointer :: src, dst

    if (c_associated(src_ptr) .and. c_associated(dst_ptr)) then
      call c_f_pointer(src_ptr, src)
      call c_f_pointer(dst_ptr, dst)
      dst = src  ! Fortran derived type assignment
    end if
  end subroutine

  function allocate_named_number_struct_container() result(ptr) bind(c)
    implicit none
    type(c_ptr) :: ptr
    type(named_number_struct_container_alloc), pointer :: ctr
    allocate(ctr)
    ptr = c_loc(ctr)
  end function

  subroutine deallocate_named_number_struct_container(ptr) bind(c)
    implicit none
    type(c_ptr), value :: ptr
    type(named_number_struct_container_alloc), pointer :: ctr
    if (c_associated(ptr)) then
      call c_f_pointer(ptr, ctr)
      deallocate(ctr)
    end if
  end subroutine

  subroutine reallocate_named_number_struct_container_data(container_ptr, lbound_, n) bind(c)
    implicit none
    type(c_ptr), value :: container_ptr
    integer(c_int), value :: lbound_
    integer(c_size_t), value :: n
    type(named_number_struct_container_alloc), pointer :: ctr

    if (.not. c_associated(container_ptr)) return
    call c_f_pointer(container_ptr, ctr)

    if (n == 0) then
      if (allocated(ctr%data)) deallocate(ctr%data)
    else
      if (allocated(ctr%data)) deallocate(ctr%data)
      allocate(ctr%data(lbound_:lbound_ + n - 1))
    end if
  end subroutine

  subroutine access_named_number_struct_container(container_ptr, d_ptr, bounds, is_allocated, elem_size) bind(c)
    use iso_c_binding
    implicit none
    type(c_ptr), value :: container_ptr
    type(c_ptr), intent(out) :: d_ptr
    integer(c_int), dimension(2), intent(out) :: bounds
    logical(c_bool), intent(out) :: is_allocated
    integer(c_size_t), intent(out) :: elem_size

    type(named_number_struct_container_alloc), pointer :: ctr

    if (.not. c_associated(container_ptr)) then
       is_allocated = .false.
       return
    endif

    call c_f_pointer(container_ptr, ctr)

    if (allocated(ctr%data)) then
      is_allocated = .true.
      bounds(1) = int(lbound(ctr%data, 1), c_int)
      bounds(2) = int(ubound(ctr%data, 1), c_int)
      ! Use intrinsic storage_size (returns bits) divided by 8 for bytes
      elem_size = storage_size(ctr%data(bounds(1))) / 8
      d_ptr = c_loc(ctr%data(bounds(1)))
    else
      is_allocated = .false.
      d_ptr = c_null_ptr
      bounds = 0
      elem_size = 0
    endif
  end subroutine
    
