    if (c_associated(ptr)) then
      call c_f_pointer(ptr, ctr)
      deallocate(ctr)
    end if
  end subroutine

  subroutine reallocate_pre_tracker_struct_container_data(container_ptr, lbound_, n) bind(c)
    implicit none
    type(c_ptr), value :: container_ptr
