  ! dispatch: twiss_struct%real (16 fields)

  subroutine twiss_struct_get_real(struct_obj_ptr, field_id, value_out) &
      bind(c, name='twiss_struct_get_real')
    type(c_ptr), intent(in), value :: struct_obj_ptr
    integer(c_int), intent(in), value :: field_id
    real(c_double), intent(out) :: value_out
    type(twiss_struct), pointer :: struct_obj
    call c_f_pointer(struct_obj_ptr, struct_obj)
    select case(field_id)
    case(0); value_out = struct_obj%beta
    case(1); value_out = struct_obj%alpha
    case(2); value_out = struct_obj%gamma
    case(3); value_out = struct_obj%phi
    case(4); value_out = struct_obj%eta
    case(5); value_out = struct_obj%etap
    case(6); value_out = struct_obj%deta_ds
    case(7); value_out = struct_obj%sigma
    case(8); value_out = struct_obj%sigma_p
    case(9); value_out = struct_obj%emit
